SELECT (SELECT count(*) FROM sqlite_schema WHERE type='table' AND name IN ('pp1','cc1','pp2','cc2')) AS table_count, (SELECT quote(x)||':'||typeof(x) FROM pp1) AS pp1_row, (SELECT quote(y)||':'||typeof(y) FROM cc1) AS cc1_row, (SELECT quote(x)||':'||typeof(x) FROM pp2) AS pp2_row, (SELECT quote(y)||':'||typeof(y) FROM cc2) AS cc2_row, (SELECT count(*) FROM pragma_foreign_key_check) AS fk_violations, (SELECT group_concat(src||'>'||dst||'('||src_col||')', ',') FROM (SELECT 'cc1' AS src, "table" AS dst, "from" AS src_col FROM pragma_foreign_key_list('cc1') UNION ALL SELECT 'cc2' AS src, "table" AS dst, "from" AS src_col FROM pragma_foreign_key_list('cc2') ORDER BY src)) AS fk_definitions, (SELECT sum(CASE WHEN lower(sql) LIKE '%deferrable initially deferred%' THEN 1 ELSE 0 END) FROM sqlite_schema WHERE type='table' AND name IN ('cc1','cc2')) AS deferred_count;